def transform(grid):
    h, w = len(grid), len(grid[0])
    clues = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    candidates = []
    for orientation in (0, 1):
        # The pattern may repeat along either diagonal direction.
        diagonals = {}
        for r, c, color in clues:
            k = c - r if orientation == 0 else c + r
            diagonals.setdefault(k, []).append(color)

        for period in range(1, max(h, w) + 1):
            pattern = {}
            valid = True
            for k, colors in diagonals.items():
                if len(set(colors)) != 1:
                    valid = False
                    break
                residue = k % period
                color = colors[0]
                if residue in pattern and pattern[residue] != color:
                    valid = False
                    break
                pattern[residue] = color
            if valid and len(pattern) == period:
                candidates.append((period, orientation, pattern))
                break

    if not candidates:
        # Fallback: use the smallest consistent period, even if some residues
        # are not explicitly represented among the clues.
        for orientation in (0, 1):
            diagonals = {}
            for r, c, color in clues:
                k = c - r if orientation == 0 else c + r
                diagonals.setdefault(k, []).append(color)
            for period in range(1, max(h, w) + 1):
