                for k, colors in diagonals.items():
                    if len(set(colors)) != 1:
                        valid = False
                        break
                    residue = k % period
                    color = colors[0]
                    if residue in pattern and pattern[residue] != color:
                        valid = False
                        break
                    pattern[residue] = color
                if valid:
                    candidates.append((period, orientation, pattern))
                    break

    period, orientation, pattern = min(candidates, key=lambda x: (x[0], x[1]))
    # Fill any unobserved residues by repeating the known sequence.
    for i in range(period):
        if i not in pattern:
            pattern[i] = 0

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            k = c - r if orientation == 0 else c + r
            row.append(pattern[k % period])
        out.append(row)
    return out
